// CAS 回滚：仅当 gitSha 仍等于本次导入写入的 expect_sha 时才回退 restore_sha，
// 防止并发邻居任务已提交更新的 sha 被旧回滚覆写；0 行 = CAS miss（调用方留痕）。
// narg：restore_sha 可空（原仓库无 sha 时回退 NULL），expect_sha 同型对齐。
// 不触碰 updatedAt：回滚是「恢复原状」而非状态演进，避免审计面把失败补偿
// 误读为一次真实更新。
func (q *Queries) RestoreRepositoryGitSha(ctx context.Context, arg RestoreRepositoryGitShaParams) (int64, error) {
	result, err := q.db.Exec(ctx, restoreRepositoryGitSha, arg.RestoreSha, arg.ID, arg.ExpectSha)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

